input.command:
which actionlint yamllint 2>/dev/null; echo "---"; python3 -c "
import sys,glob
try:
    import yaml
except ImportError:
    print('pyyaml: not installed'); sys.exit(0)
for f in sorted(glob.glob('.github/workflows/*.yml')):
    yaml.safe_load(open(f))
    print('ok', f)
"

